"use strict";(globalThis.webpackChunkmy_website||=[]).push([[9836],{24897(t){t.exports=JSON.parse('{"slug":"datum","title":"Datum","short":"A piece of data attached to a UTxO that a smart contract can read when deciding whether the UTxO can be spent.","category":"smart-contracts","aliases":["Datums","Inline Datum"],"mentalModel":"A sticky note attached to a UTxO. The smart contract reads what\'s on it before deciding to spend the UTxO.","related":["redeemer","validator","eutxo","smart-contract"],"sources":[],"link":null,"level":"intermediate","body":"A piece of data attached to a transaction output in Cardano\'s eUTxO model. The datum acts like state that travels with the output: a smart contract sees it whenever someone tries to spend the output and decides, based on its contents plus the redeemer, whether to allow the spend.\\n\\nInline datums (introduced with the Vasil hard fork) store the data directly on the output; earlier outputs stored only a hash of the datum, with the full data supplied later by the spending transaction."}')}}]);